"""Fetch pinned official brand assets for package builds; never commit generated bytes."""

from __future__ import annotations

import argparse
import base64
import hashlib
import json
import urllib.request
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"
MAX_ICON_BYTES = 2 * 1024 * 1024


def verified_icon(data: bytes, expected_sha256: str) -> bytes:
    if len(data) > MAX_ICON_BYTES or not data.startswith(PNG_SIGNATURE):
        raise ValueError("The official icon is not a supported PNG")
    if hashlib.sha256(data).hexdigest() != expected_sha256:
        raise ValueError("The official icon SHA256 does not match the pinned asset")
    return data


def fetch_icon(root: Path = ROOT) -> bytes:
    manifest = json.loads((root / "brand-assets.json").read_text())
    icon = manifest["icon"]
    url = icon["url"]
    if not url.startswith("https://cdn.acedata.cloud/"):
        raise ValueError("Official package icons must come from the Ace Data Cloud CDN")
    # Reuse only content that still matches the immutable asset digest.
    for relative in ("vscode/icon.png", "jetbrains/src/main/resources/META-INF/pluginIcon.png"):
        path = root / relative
        if path.is_file():
            try:
                return verified_icon(path.read_bytes(), icon["sha256"])
            except ValueError:
                pass
    request = urllib.request.Request(url, headers={"User-Agent": "AceMusic-package-build/1"})
    with urllib.request.urlopen(request, timeout=30) as response:
        return verified_icon(response.read(MAX_ICON_BYTES + 1), icon["sha256"])


def prepare_assets(target: str, root: Path = ROOT) -> None:
    data = fetch_icon(root)
    if target in {"all", "vscode"}:
        destination = root / "vscode/icon.png"
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(data)
    if target in {"all", "jetbrains"}:
        destination = root / "jetbrains/src/main/resources/META-INF"
        destination.mkdir(parents=True, exist_ok=True)
        (destination / "pluginIcon.png").write_bytes(data)
        encoded = base64.b64encode(data).decode("ascii")
        svg = (
            '<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" '
            'width="40" height="40" viewBox="0 0 40 40">'
            '<image width="40" height="40" preserveAspectRatio="xMidYMid meet" '
            f'xlink:href="data:image/png;base64,{encoded}"/></svg>\n'
        )
        for name in ("pluginIcon.svg", "pluginIcon_dark.svg"):
            (destination / name).write_text(svg)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--target", choices=["all", "vscode", "jetbrains"], default="all")
    args = parser.parse_args()
    prepare_assets(args.target)
    print(f"Verified official ACE Music icon prepared for {args.target}")


if __name__ == "__main__":
    main()
